/// @title A module dedicated for handling the collateral deposit request from user
module protocol::deposit;

use std::type_name::{Self, TypeName};

use sui::coin::Coin;
use sui::clock::Clock;
use sui::event::emit;

use protocol::liquidity_miner::get_deposit_reward_type;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::app::ProtocolApp;

public struct DepositEvent has copy, drop {
    minter: address,

    market: TypeName,
    obligation: ID,

    deposit_asset: TypeName,
    deposit_amount: u64,

    ctoken_amount: u64,
    total_ctoken_amount: u64,

    time: u64,
}

public fun deposit<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,

    obligation_owner_cap: &ObligationOwnerCap,

    coin: Coin<CoinType>,
    clock: &Clock,

    ctx: &TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock.timestamp_ms() / 1000;
    let deposit_amount = coin.value();

    let (ctoken_amount, total_ctoken_amount) = market.handle_mint(obligation_owner_cap.id(), coin, now);

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_deposit_reward_type(),
        obligation_owner_cap.id(),
        total_ctoken_amount,
        clock
    );

    emit(DepositEvent {
        minter: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        deposit_asset: type_name::with_defining_ids<CoinType>(),
        deposit_amount,

        ctoken_amount,
        total_ctoken_amount,
        time: now,
    });
}

